const staticData = this.getWorkflowStaticData('global');
staticData.autotaskStaleConfig = items[0]?.json ?? {};
return items;

const staticData = this.getWorkflowStaticData('global');
const config = staticData.autotaskStaleConfig || {};
const cutoff = new Date();
const staleHours = Number(config.staleAfterHours) || 48;
cutoff.setHours(cutoff.getHours() - staleHours);
const excludedStatuses = Array.isArray(config.awaitingCustomerStatusIds) ? config.awaitingCustomerStatusIds.map((id) => Number(id)) : [];

const results = items
  .map((item) => {
    const data = item.json;
    const statusId = data.statusId ?? data.status?.id ?? null;
    const statusName = data.status?.name ?? data.status ?? null;
    const lastActivityDate = data.lastActivityDate ? new Date(data.lastActivityDate) : null;

    return {
      json: {
        id: data.id,
        ticketNumber: data.ticketNumber,
        title: data.title,
        statusId,
        statusName,
        queueId: data.queueID ?? data.queueId ?? null,
        queueName: data.queueName ?? data.queue?.name ?? null,
        priorityId: data.priorityId ?? data.priorityID ?? data.priority?.id ?? null,
        priorityName: data.priority?.name ?? data.priority ?? null,
        assignedResourceId: data.assignedResourceID ?? data.assignedResourceId ?? null,
        assignedResourceName: data.assignedResourceName ?? data.assignedResource?.name ?? 'Unassigned',
        assignedResourceEmail: data.assignedResourceEmailAddress ?? data.assignedResource?.email ?? config.serviceDeskEmail,
        lastActivityDate: lastActivityDate ? lastActivityDate.toISOString() : null,
        createDate: data.createDate ?? null,
        dueDateTime: data.dueDateTime ?? null
      }
    };
  })
  .filter((item) => {
    const statusId = item.json.statusId;
    if (statusId && excludedStatuses.includes(Number(statusId))) {
      return false;
    }

    const lastActivity = item.json.lastActivityDate ? new Date(item.json.lastActivityDate) : null;
    if (!lastActivity) {
      return true;
    }

    return lastActivity <= cutoff;
  })
  .map((item) => {
    const lastActivity = item.json.lastActivityDate ? new Date(item.json.lastActivityDate) : null;
    const ageHours = lastActivity ? Math.floor((Date.now() - lastActivity.getTime()) / (1000 * 60 * 60)) : null;
    const ageDays = ageHours !== null ? Number((ageHours / 24).toFixed(1)) : null;

    return {
      json: {
        ...item.json,
        cutoffHours: staleHours,
        cutoffAt: cutoff.toISOString(),
        ageHours,
        ageDays
      }
    };
  });

return results;

const staticData = this.getWorkflowStaticData('global');
const config = staticData.autotaskStaleConfig || {};

if (!items.length) {
  return [];
}

const recipients = Array.isArray(config.notificationRecipients) && config.notificationRecipients.length
  ? config.notificationRecipients
  : [config.serviceDeskEmail].filter(Boolean);

if (!recipients.length) {
  throw new Error('No notification recipients configured. Please populate notificationRecipients or serviceDeskEmail in the Set Config node.');
}

const fromEmail = config.fromEmail || config.serviceDeskEmail;
if (!fromEmail) {
  throw new Error('No fromEmail configured. Please set fromEmail in the Set Config node.');
}

const ticketUrlBase = config.ticketUrlBase || '';
const staleDays = Number(((items[0].json.cutoffHours || 48) / 24).toFixed(1));

const rows = items.map((item) => {
  const ticket = item.json;
  const reference = ticket.ticketNumber || ticket.id;
  const ticketUrl = ticketUrlBase ? `${ticketUrlBase}${reference}` : '';
  const link = ticketUrl ? `<a href="${ticketUrl}">${reference}</a>` : reference;
  const age = ticket.ageDays !== null && ticket.ageDays !== undefined ? `${ticket.ageDays} day(s)` : 'Unknown';

  return `<tr>
    <td>${link || ''}</td>
    <td>${ticket.title || ''}</td>
    <td>${ticket.assignedResourceName || 'Unassigned'}</td>
    <td>${ticket.statusName || ''}</td>
    <td>${ticket.queueName || ''}</td>
    <td>${age}</td>
    <td>Last activity: ${ticket.lastActivityDate || 'Unknown'}<br/>Action: Provide customer-facing update or take the next resolution step.</td>
  </tr>`;
}).join('');

const html = `<p>The following ${items.length} Autotask ticket(s) have had no activity for at least ${staleDays} day(s) and are not waiting on the customer.</p>
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;">
  <thead>
    <tr>
      <th>Ticket</th>
      <th>Title</th>
      <th>Owner</th>
      <th>Status</th>
      <th>Queue</th>
      <th>Age</th>
      <th>Summary</th>
    </tr>
  </thead>
  <tbody>
    ${rows}
  </tbody>
</table>
<p>Please review each ticket, add an update for the customer, or escalate to the appropriate team.</p>`;

const plain = `The following ${items.length} Autotask ticket(s) need attention:
` + items.map((item) => {
  const ticket = item.json;
  const age = ticket.ageDays !== null && ticket.ageDays !== undefined ? `${ticket.ageDays} day(s)` : 'unknown age';
  const reference = ticket.ticketNumber || ticket.id;
  return `• ${reference}: ${ticket.title || ''} | Owner: ${ticket.assignedResourceName || 'Unassigned'} | Status: ${ticket.statusName || ''} | Age: ${age}`;
}).join('
');

return [
  {
    json: {
      subject: `Autotask tickets needing updates (${items.length})`,
      htmlBody: html,
      fallbackPlainText: plain,
      to: recipients,
      fromEmail
    }
  }
];
